import{_ as o,o as a,c as i,a2 as c}from"./chunks/framework.XctAhZuT.js";const n="/docs/images/guide/anki-import-flow.svg",f=JSON.parse('{"title":"导入 Anki 牌组","description":"本页描述 Official-first 导入。Android arm64 与 iOS 走同一条生产路径。","frontmatter":{"description":"本页描述 Official-first 导入。Android arm64 与 iOS 走同一条生产路径。"},"headers":[],"relativePath":"guide/anki-import.md","filePath":"guide/anki-import.md","lastUpdated":1790697640000}'),t={name:"guide/anki-import.md"};function l(d,e,s,r,p,u){return a(),i("div",null,[...e[0]||(e[0]=[c(`<h1 id="导入-anki-牌组" tabindex="-1">导入 Anki 牌组 <a class="header-anchor" href="#导入-anki-牌组" aria-label="Permalink to &quot;导入 Anki 牌组&quot;">​</a></h1><p>本页描述 Official-first 导入。Android arm64 与 iOS 走同一条生产路径。</p><div class="warning custom-block"><p class="custom-block-title">验收状态</p><p>Official Anki 当前口径是**「验收 NO-GO；迁移中」**：Android 写侧仅在真机以 <strong>debug 构建</strong>验证过，生产 bundle 完整用户流尚未验证；iOS 侧为模拟器 E2E。不得宣称「迁移完成」或「Android 可正常使用」。</p></div><div class="warning custom-block"><p class="custom-block-title">只支持 .apkg</p><p>生产导入输入是 <code>.apkg</code>。选择 <code>.colpkg</code> 会得到明确的不支持提示与人工引导（需先在桌面 Anki 重新导出为 <code>.apkg</code>）；内存示例牌组不属于生产导入合同。</p></div><h2 id="导入前检查" tabindex="-1">导入前检查 <a class="header-anchor" href="#导入前检查" aria-label="Permalink to &quot;导入前检查&quot;">​</a></h2><ul><li>保留原始牌组文件作为备份。</li><li>确认文件可以在桌面 Anki 中打开。</li><li>检查可用存储空间，媒体牌组需要额外空间。</li></ul><h2 id="执行路径" tabindex="-1">执行路径 <a class="header-anchor" href="#执行路径" aria-label="Permalink to &quot;执行路径&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>选择 .apkg</span></span>
<span class="line"><span>  -&gt; 解析导入元数据</span></span>
<span class="line"><span>  -&gt; 生成一次 AnkiImportExecutionPlan（选文件时冻结，后续步骤不重读开关）</span></span>
<span class="line"><span>  -&gt; 写入 Official Collection</span></span>
<span class="line"><span>  -&gt; 建立课程投影</span></span>
<span class="line"><span>  -&gt; 注册 sourceId 与复习入口</span></span></code></pre></div><p>向导分五步：选文件 → 解析 → 预览 → 执行 → 完成（失败态保留返回步骤）。</p><p><img src="`+n+'" alt="Anki 导入五步向导：输入边界 / 所有权 / notetype 投影" loading="lazy"></p><p>生产 Android 不同时写入 Legacy NoteStore 和 Turna Anki SRS。正式卡片由 Official Collection 持有，正式评分由 Official scheduler 处理。</p><h2 id="导入预览" tabindex="-1">导入预览 <a class="header-anchor" href="#导入预览" aria-label="Permalink to &quot;导入预览&quot;">​</a></h2><p>预览页展示：</p><ul><li><strong>牌组树</strong>（deck tree）与每组真实卡数（含后代累计）——不是今日到期数。</li><li><strong>notetype 识别结果</strong>：证据驱动识别器（<code>lib/application/anki_import/recognition/</code>）按 notetype 级判定，给出每种 notetype 的投影建议；可逐个确认或跳过。</li><li>需要人工映射时（<code>needsMapping</code>），进入映射页手工指定字段角色。</li></ul><p>字段识别用词表（<code>field_roles.dart</code>）按字段名匹配角色，例如：</p><ul><li>单元标签：<code>unit</code>、<code>chapter</code>、<code>单元</code>、<code>章</code></li><li>课时标签：<code>lesson</code>、<code>topic</code>、<code>课</code>、<code>节</code></li><li>正面：<code>front</code>、<code>question</code>、<code>正面</code>、<code>题目</code>、<code>题干</code> 等</li><li>背面：<code>back</code>、<code>answer</code>、<code>背面</code>、<code>答案</code> 等</li></ul><blockquote><p><code>解析</code> 不属于背面（response）角色，它绑定到额外说明（extra）角色，以免与答案字段混淆。完整词表见 <code>recognition/lexicon/field_roles.dart</code>。</p></blockquote><h2 id="notetype-投影目标" tabindex="-1">Notetype 投影目标 <a class="header-anchor" href="#notetype-投影目标" aria-label="Permalink to &quot;Notetype 投影目标&quot;">​</a></h2><p>每种 notetype 可映射为以下投影（<code>OfficialAnkiProjectionKind</code>）：</p><p><code>showWord</code>（词条卡）、<code>flip</code>（翻卡）、<code>multipleChoice</code>、<code>multiSelect</code>、<code>listenPick</code>（听音选择）、<code>typeAnswer</code>（键入答案）、<code>fillBlank</code>（cloze/填空）、<code>translate</code>（翻译）、<code>canonicalLink</code>（链接到规范资源条目）。</p><p>操作顺序：</p><ol><li>检查自动识别结果。</li><li>检查 front / back 字段索引。</li><li>查看首张 note 的文本预览。</li><li>必要时手动覆盖。</li></ol><h2 id="调度状态" tabindex="-1">调度状态 <a class="header-anchor" href="#调度状态" aria-label="Permalink to &quot;调度状态&quot;">​</a></h2><p>导入会携带原牌组的调度状态。官方导入 saga 与导入服务都以 <code>withScheduling: true</code> 调用引擎（引擎签名里该参数默认值同样是 <code>true</code>），因此卡片按原牌组的到期与间隔进入 Official 复习，而不是作为新卡重来。</p><p>无论哪条路径，排期状态都由 Official scheduler 持有 —— 不回退到 Turna FSRS。</p><h2 id="失败处理" tabindex="-1">失败处理 <a class="header-anchor" href="#失败处理" aria-label="Permalink to &quot;失败处理&quot;">​</a></h2><p>导入失败时不要重复快速点击导入。先检查错误发生在解析、Official runtime、媒体复制还是课程投影阶段。媒体复制可 best-effort；Collection 写入失败必须明确回滚或标记失败。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/docs/guide/anki">Anki 集成</a></li><li><a href="/docs/guide/anki-rendering">卡片渲染与网络隔离</a></li><li><a href="/docs/guide/troubleshooting#anki">故障排查</a></li></ul>',29)])])}const k=o(t,[["render",l]]);export{f as __pageData,k as default};
